import type { IncomingMessage, ServerResponse } from "node:http";
import type { Request, Response } from "express";
// @ts-expect-error Generated by the build script; the bundle has no source declaration.
import { createApp } from "../dist/api-handler.js";

const appPromise = createApp({ serveFrontend: false });

export default async function handler(req: IncomingMessage, res: ServerResponse) {
  const requestUrl = new URL(req.url ?? "/", "http://vercel.local");
  const routePath = requestUrl.searchParams.get("path");
  if (routePath !== null) {
    requestUrl.searchParams.delete("path");
    const query = requestUrl.searchParams.toString();
    req.url = `/api/${routePath}${query ? `?${query}` : ""}`;
  }

  const app = await appPromise;
  return app(req as Request, res as Response);
}
